public void testAwait_Zero() throws InterruptedException {
    final Mutex sync = new Mutex();
    final ConditionObject c = sync.newCondition();
    sync.acquire();
    assertTrue(c.awaitNanos(0L) <= 0);
    assertFalse(c.await(0L, NANOSECONDS));
    sync.release();
}

