assertFalse(manager.containsWatcher("/node1", watcher1, null));
assertFalse(manager.containsWatcher("/node1", watcher1, WatcherMode.STANDARD));
assertFalse(manager.containsWatcher("/node1", watcher1, WatcherMode.PERSISTENT));

