  expectedSubgraph.addEdge(N1, N2, E12);
  expectedSubgraph.addEdge(N2, N1, E21);
  expectedSubgraph.addEdge(N4, N4, E44);

  assertThat(inducedSubgraph(directedGraph, nodeSubset)).isEqualTo(expectedSubgraph);
}

